// Water & Drainage Management AI Reasoning Node
const complaint = $('Webhook: Receive Water Complaint').first().json.body || {};
const weather = $('Weather API: Precipitation Telemetry').first().json || {};
const history = $('Database: Check Nearby Flood History').first().json || {};

const desc = complaint.description || '';
const textCorpus = desc.toLowerCase();
const address = complaint.location?.address || 'Pul Prahladpur Underpass, MB Road';
const lat = complaint.location?.latitude || 28.5135;
const lng = complaint.location?.longitude || 77.2882;
const rainMmHr = weather.precipitation_rate_mm_hr || 38.5;
const isRainActive = rainMmHr > 5.0;
const clusterCount = history.matched_count || 0;
const isHotspot = history.is_chronic_hotspot || false;

// Classify Water Issue
let category = 'DRAINAGE_AND_WATERLOGGING';
let possibleCause = 'Stormwater drain siltation and high rainfall intensity';
let severity = 'HIGH';

if (textCorpus.includes('pipeline') || textCorpus.includes('burst') || textCorpus.includes('drinking water')) {
  category = 'PIPELINE_RUPTURE';
  possibleCause = 'Main freshwater distribution pipe fracture / pressure surge';
  severity = 'HIGH';
} else if (textCorpus.includes('underpass') || textCorpus.includes('subway') || textCorpus.includes('stalled cars') || textCorpus.includes('feet')) {
  category = 'CRITICAL_UNDERPASS_INUNDATION';
  possibleCause = 'Underpass drainage sump pump failure during active precipitation';
  severity = 'CRITICAL';
} else if (textCorpus.includes('sewage') || textCorpus.includes('smell') || textCorpus.includes('overflow')) {
  category = 'SEWAGE_DRAIN_BLOCKAGE';
  possibleCause = 'Trunk sewer line choke by plastic debris and silt buildup';
  severity = 'HIGH';
}

// Action recommendations
const actions = [];
if (severity === 'CRITICAL') {
  actions.push('Deploy 2x High-Capacity Diesel Dewatering Pumps (50 HP) to clear underpass within 90 minutes.');
  actions.push('Barricade underpass approaches immediately to prevent vehicular stranding.');
  actions.push('Dispatch Municipal Drainage Quick Response Team to inspect gravity outfall valve.');
} else if (category === 'PIPELINE_RUPTURE') {
  actions.push('Isolate sluice valve #6 to prevent potable water loss.');
  actions.push('Dispatch emergency pipeline repair gang with replacement collar pipe.');
} else {
  actions.push('Dispatch Super Sucker / Jetting machine to clear local stormwater line.');
  actions.push('Schedule post-monsoon desilting inspection for catchment zone.');
}

const output = {
  incident_id: 'WTR-INC-' + Date.now(),
  complaint_id: complaint.complaint_id || 'CMP-WTR-005',
  source_agent: 'water_management_agent',
  water_issue_report: `Inundation & water issue reported at ${address}. Type: ${category}. Rainfall rate: ${rainMmHr} mm/hr. Local complaint cluster detected: ${clusterCount} reports in vicinity (Chronic hotspot: ${isHotspot ? 'YES' : 'NO'}). Assessed severity: ${severity}.`,
  location: {
    address: address,
    latitude: lat,
    longitude: lng,
    is_chronic_flood_spot: isHotspot
  },
  severity: severity,
  possible_cause: possibleCause,
  recommended_action: actions.join(' | '),
  recommended_equipment: severity === 'CRITICAL' ? ['50 HP High Flow Dewatering Pump', 'Safety Barricades', 'Mobile Generator'] : ['Super Sucker Jetting Truck'],
  rainfall_data: {
    precipitation_rate_mm_hr: rainMmHr,
    condition: weather.weather_condition || 'RAIN'
  },
  cluster_detected: clusterCount > 1,
  escalate_to_command: severity === 'CRITICAL' || severity === 'HIGH',
  command_alert_headline: `[WATER ALERT - ${severity}] ${category} at ${address}`
};

return output;
